[package]
name = "test18"
version = "1.0.0"
edition = "2021"
publish = false
description = "Pure-std Rust port of tests/test18.cpp and the sortedcontainers C++ header"

# The entry file lives in the package root, and the library it uses is reached through
# `mod` declarations rather than a separate crate. That keeps a bare `rustc test18.rs`
# working alongside `cargo build --release`.
[[bin]]
name = "test18"
path = "test18.rs"

# No `[dependencies]` section: the port is std-only by requirement.

[profile.release]
opt-level = 3
